use vstd::prelude::*;

verus! {

fn max_of_list(lst: Vec<i32>) -> (result: i32)
    requires
        lst.len() > 0,
    ensures
        exists|i: int|
            0 <= i < lst.len() &&
            result == lst[i],
        forall|j: int|
            0 <= j < lst.len() ==> lst[j] <= result,
{
    let mut idx: usize = 0;
    let mut max_val: i32 = lst[0];

    while idx < lst.len()
        invariant
            lst.len() > 0,
            0 <= idx <= lst.len(),
            // current max_val is some element among the prefix [0, idx)
            exists|i: int| 0 <= i < idx && max_val == lst[i],
            // max_val upper-bounds the prefix [0, idx)
            forall|j: int| 0 <= j < idx ==> lst[j] <= max_val,
        decreases lst.len() - idx,
    {
        if lst[idx] > max_val {
            max_val = lst[idx];
        }
        idx = idx + 1;
    }

    max_val
}

}

